static inline _Bool set_log_debug(char *name, _Bool val)
{
  if (strcmp(name, "PRACH") == 0) { g_log->debug_mask.DEBUG_PRACH = val; return 1; }; if (strcmp(name, "UE_PHYPROC") == 0) { g_log->debug_mask.DEBUG_UE_PHYPROC = val; return 1; }; if (strcmp(name, "LTEESTIM") == 0) { g_log->debug_mask.DEBUG_LTEESTIM = val; return 1; }; if (strcmp(name, "DLCELLSPEC") == 0) { g_log->debug_mask.DEBUG_DLCELLSPEC = val; return 1; }; if (strcmp(name, "ULSCH") == 0) { g_log->debug_mask.DEBUG_ULSCH = val; return 1; }; if (strcmp(name, "RRC") == 0) { g_log->debug_mask.DEBUG_RRC = val; return 1; }; if (strcmp(name, "PDCP") == 0) { g_log->debug_mask.DEBUG_PDCP = val; return 1; }; if (strcmp(name, "DFT") == 0) { g_log->debug_mask.DEBUG_DFT = val; return 1; }; if (strcmp(name, "ASN1") == 0) { g_log->debug_mask.DEBUG_ASN1 = val; return 1; }; if (strcmp(name, "CTRLSOCKET") == 0) { g_log->debug_mask.DEBUG_CTRLSOCKET = val; return 1; }; if (strcmp(name, "SECURITY") == 0) { g_log->debug_mask.DEBUG_SECURITY = val; return 1; }; if (strcmp(name, "NAS") == 0) { g_log->debug_mask.DEBUG_NAS = val; return 1; }; if (strcmp(name, "DLSCH_DECOD") == 0) { g_log->debug_mask.DEBUG_DLSCH_DECOD = val; return 1; }; if (strcmp(name, "UE_TIMING") == 0) { g_log->debug_mask.DEBUG_UE_TIMING = val; return 1; }; if (strcmp(name, "F1AP") == 0) { g_log->debug_mask.DEBUG_F1AP = val; return 1; };;
  printf("Error: setting log debug of %s option, not existing\n", name);
  return 0;
}
