static inline int lenWithCrc(int nbSeg, int len)
{
  if (nbSeg > 1)
    return (len + 24 + 24 * nbSeg) / nbSeg;
  return len + (len > 3824 ? 24 : 16);
}
static inline int crcType(int nbSeg, int len)
{
  if (nbSeg > 1)
    return 1;
  return len > 3824 ? 0 : 2;
}
